// Converte o CSV de investimentos (texto) em uma lista de objetos
const csv = $input.first().json.data;
const linhas = csv.trim().split('\n').map(l => l.trim()).filter(Boolean);
const cabecalho = linhas.shift().split(',').map(c => c.trim());

const investimentos = linhas.map(linha => {
  const valores = linha.split(',');
  return Object.fromEntries(cabecalho.map((col, i) => [col, (valores[i] || '').trim()]));
});

return [{ json: { investimentos } }];

// Cruza cada cliente (vindo do Webhook) com os investimentos do seu perfil
// que cabem no saldo dele
const { body, investimentos } = $input.first().json;
const clientes = Array.isArray(body) ? body : (body.clientes || []);

// "R$ 12.500,00" -> 12500
const paraNumero = s => Number(String(s).replace('R$', '').split('.').join('').replace(',', '.').trim()) || 0;

const resultado = clientes.map(cliente => {
  const perfil = String(cliente.perfil || '').trim().toLowerCase();
  const saldo = paraNumero(cliente.saldo);
  const recomendacoes = investimentos.filter(inv =>
    inv.perfil.toLowerCase() === perfil && saldo >= Number(inv.minimo)
  );
  return { ...cliente, saldoNumerico: saldo, recomendacoes };
});

return [{ json: { clientes: resultado } }];

// Separa um item por cliente e monta o briefing (prompt) para o LLM
const { clientes } = $input.first().json;

return clientes.map(cliente => {
  const produtos = cliente.recomendacoes.length
    ? cliente.recomendacoes
        .map(r => `- ${r.produto} (rentabilidade: ${r.rentabilidade}, aplicação mínima: R$ ${r.minimo})`)
        .join('\n')
    : '- Nenhum produto do perfil cabe no saldo atual';

  const prompt = [
    'Escreva um email curto de recomendação de investimentos para o cliente abaixo.',
    '',
    `Nome: ${cliente.nome}`,
    `Perfil de investidor: ${cliente.perfil}`,
    `Saldo disponível: ${cliente.saldo}`,
    'Produtos indicados para o perfil e saldo:',
    produtos,
    '',
    'Regras:',
    '- Trate o cliente pelo primeiro nome, em tom cordial e profissional.',
    '- Cite apenas os produtos listados acima, sem inventar outros nem prometer rentabilidade.',
    '- Se nenhum produto couber no saldo, sugira aportar mais ou falar com um assessor.',
    '- Máximo de 120 palavras no corpo e assine como "Equipe de Investimentos".',
    'Responda somente em JSON no formato {"assunto": "...", "corpo": "..."}.'
  ].join('\n');

  return { json: { ...cliente, prompt } };
});

// Junta a resposta do LLM com os dados do cliente (mesma ordem dos itens)
const clientes = $('Code in JavaScript2').all();

return $input.all().map((item, i) => {
  const cliente = clientes[i].json;
  const texto = (item.json.content?.parts || []).map(p => p.text || '').join('').trim();

  let email;
  try {
    email = JSON.parse(texto.replace(/^```(json)?/, '').replace(/```$/, '').trim());
  } catch (e) {
    email = { assunto: 'Recomendações de investimento para você', corpo: texto };
  }

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      recomendacoes: cliente.recomendacoes.map(r => r.produto),
      assunto: email.assunto,
      mensagem: email.corpo
    }
  };
});
